using FoodExpiryApp.Models; namespace FoodExpiryApp; public class ProductEditPage:ContentPage { readonly ProductRepository repo; readonly Entry name=new(){Placeholder="Название"}; readonly Entry brand=new(){Placeholder="Бренд"}; readonly Entry variant=new(){Placeholder="Разновидность, например 2.5%"}; readonly Entry volume=new(){Placeholder="Объём / масса, например 0,930 л"}; readonly Entry code=new(){Placeholder="Штрихкод / код маркировки (необязательно)"}; readonly Picker category=new(){Title="Категория",ItemsSource=new[]{"Молочные","Напитки","Мясо и рыба","Овощи и фрукты","Заморозка","Другое"},SelectedIndex=5}; readonly DatePicker expiry=new(){Date=DateTime.Today.AddDays(7)}; public ProductEditPage(ProductRepository r){repo=r;Title="Добавить продукт";BackgroundColor=Color.FromArgb("#111116");var save=new Button{Text="Сохранить",BackgroundColor=Color.FromArgb("#A978F5"),TextColor=Colors.Black};save.Clicked+=Save;Content=new ScrollView{Content=new VerticalStackLayout{Padding=22,Spacing=12,Children={new Label{Text="Новый продукт",FontSize=26,TextColor=Colors.White,FontAttributes=FontAttributes.Bold},name,brand,variant,volume,code,category,new Label{Text="Срок годности",TextColor=Colors.White},expiry,save}}};} async void Save(object? s,EventArgs e){if(string.IsNullOrWhiteSpace(name.Text)){await DisplayAlert("Название","Введите название продукта.","ОК");return;}await repo.Save(new Product{Name=name.Text.Trim(),Brand=brand.Text?.Trim()??"",Variant=variant.Text?.Trim()??"",Volume=volume.Text?.Trim()??"",Barcode=code.Text?.Trim()??"",Category=category.SelectedItem?.ToString()??"Другое",ExpiryDate=expiry.Date});await Navigation.PopAsync();} }
